import { translate } from "./messages.js";
import { teamLabel } from "./labels.js";
import { taskWhen } from "../task-date.js";

// Report structure and enum cells are generated by the product. Names, task titles,
// descriptions, ticket numbers, references and notes are always left as authored.
export function reportTitle(title, locale) {
  const prefix = "Employee Monthly Report · ";
  return title.startsWith(prefix) ? `${translate(locale, "Employee Monthly Report")} · ${title.slice(prefix.length)}` : translate(locale, title);
}

export function reportHeader(header, locale) {
  const activity = /^(#\d+ )(.+)$/.exec(header);
  return activity ? `${activity[1]}${translate(locale, activity[2])}` : translate(locale, header);
}

export function reportCell(sheet, key, value, locale) {
  if (value === null || value === undefined || value === "") return value;
  if (sheet === "Tasks" && (key === "start" || key === "end")) return taskWhen(String(value), locale);
  if (key === "team") return teamLabel(value, locale);
  if (["status", "quality", "complexity", "role", "verdict"].includes(key)) return translate(locale, value);
  if (sheet === "Routine Activity" && key === "k") return translate(locale, value);
  return value;
}
